def total(lines, tax_rate=0.0):
    subtotal = sum(qty * price for qty, price in lines)
    return round(subtotal * (1 + tax_rate), 2)

def total(lines, tax_rate=0.0, discount=0.0):
    subtotal = sum(qty * price for qty, price in lines)
    subtotal -= subtotal * discount
    return round(subtotal * (1 + tax_rate), 2)
